<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
const slides=[...document.querySelectorAll('.gallery-slide')],thumbs=[...document.querySelectorAll('.gallery-thumb')];let galleryIndex=0;
function showSlide(index){if(!slides.length)return;galleryIndex=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('active',i===galleryIndex));thumbs.forEach((thumb,i)=>thumb.classList.toggle('active',i===galleryIndex));const active=slides[galleryIndex],stage=document.querySelector('.gallery-stage');stage?.style.setProperty('--gallery-backdrop',`url("${active.src.replace(/"/g,'\\"')}")`);document.getElementById('gallery-current')&&(document.getElementById('gallery-current').textContent=galleryIndex+1);document.getElementById('lightbox-current')&&(document.getElementById('lightbox-current').textContent=galleryIndex+1);document.getElementById('lightbox-image')&&(document.getElementById('lightbox-image').src=active.src);thumbs[galleryIndex]?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}
showSlide(0);document.querySelector('.gallery-prev')?.addEventListener('click',()=>showSlide(galleryIndex-1));document.querySelector('.gallery-next')?.addEventListener('click',()=>showSlide(galleryIndex+1));thumbs.forEach((thumb,index)=>thumb.addEventListener('click',()=>showSlide(index)));document.querySelector('.gallery-stage')?.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showSlide(galleryIndex-1);if(e.key==='ArrowLeft')showSlide(galleryIndex+1)});let touchStart=0;document.querySelector('.gallery-stage')?.addEventListener('touchstart',e=>touchStart=e.changedTouches[0].clientX,{passive:true});document.querySelector('.gallery-stage')?.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>45)showSlide(galleryIndex+(delta>0?-1:1))},{passive:true});
const lightbox=document.getElementById('gallery-lightbox');document.getElementById('gallery-expand')?.addEventListener('click',()=>lightbox?.showModal());document.querySelector('.lightbox-close')?.addEventListener('click',()=>lightbox.close());document.querySelector('.lightbox-prev')?.addEventListener('click',()=>showSlide(galleryIndex-1));document.querySelector('.lightbox-next')?.addEventListener('click',()=>showSlide(galleryIndex+1));lightbox?.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
document.querySelectorAll('.tab-button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tab-button').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('.tab-panel').forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===button.dataset.tab))}));
const favoriteKey='ozman_real_estate_favorites',propertyId={{ $property->id }},favorite=document.getElementById('favorite');function favoriteIds(){try{return JSON.parse(localStorage.getItem(favoriteKey)||'[]').map(Number)}catch{return[]}}function paintFavorite(){const active=favoriteIds().includes(propertyId);favorite.textContent=(active?'♥ ':'♡ ')+@json($copy['favorite']);favorite.style.color=active?'#ff718c':''}favorite.addEventListener('click',()=>{let ids=favoriteIds();ids=ids.includes(propertyId)?ids.filter(id=>id!==propertyId):[...ids,propertyId];localStorage.setItem(favoriteKey,JSON.stringify(ids));paintFavorite()});paintFavorite();
document.getElementById('share').addEventListener('click',async()=>{const data={title:@json($shareTitle),text:@json($shareDescription),url:location.href};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(@json($shareText));alert('تم نسخ مواصفات العقار والرابط')}}catch(error){if(error.name!=='AbortError')console.error(error)}});
@if($property->purpose==='sale')function calculate(){const price={{ (float)$property->price }},down=Number(document.getElementById('down').value||0),years=Number(document.getElementById('years').value||1),annual=Number(document.getElementById('interest').value||0)/100,principal=Math.max(0,price-down),months=years*12,rate=annual/12,payment=rate?principal*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1):principal/months;document.getElementById('calculation').textContent=@json($copy['monthly'])+': '+Math.round(payment).toLocaleString()+' {{ $property->currency }}'}document.querySelectorAll('.calculator input').forEach(input=>input.addEventListener('input',calculate));calculate();@endif
@if($property->latitude&&$property->longitude)
if(window.L){const destination=[{{ $property->latitude }},{{ $property->longitude }}],map=L.map('property-map').setView(destination,15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);L.marker(destination).addTo(map).bindPopup(@json($title)).openPopup();const result=document.getElementById('distance-result'),button=document.getElementById('calculate-distance');button.addEventListener('click',()=>{button.disabled=true;result.textContent='جاري تحديد موقعك...';navigator.geolocation?.getCurrentPosition(position=>{const origin=[position.coords.latitude,position.coords.longitude],rad=v=>v*Math.PI/180,dLat=rad(destination[0]-origin[0]),dLng=rad(destination[1]-origin[1]),a=Math.sin(dLat/2)**2+Math.cos(rad(origin[0]))*Math.cos(rad(destination[0]))*Math.sin(dLng/2)**2,distance=6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));L.marker(origin).addTo(map).bindPopup('موقعك الحالي');L.polyline([origin,destination],{color:'#18d7ef',weight:4,dashArray:'8 8'}).addTo(map);map.fitBounds([origin,destination],{padding:[35,35]});result.classList.add('ready');result.innerHTML=`${distance<1?Math.round(distance*1000)+' متر':distance.toFixed(1)+' كم'} · <a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&origin=${origin[0]},${origin[1]}&destination=${destination[0]},${destination[1]}">{{ $copy['directions'] }}</a>`;button.disabled=false},()=>{result.textContent='تعذر تحديد موقعك. فعّل إذن الموقع وافتح الصفحة عبر HTTPS.';button.disabled=false},{enableHighAccuracy:true,timeout:12000})})}
@endif
</script>
